$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$script=Join-Path $root 'scripts\test-startup-contract.ps1';$out=Join-Path $env:TEMP 'beadwise-startup-contract.json'
try{& $script -OutputPath $out;$r=Get-Content -Raw $out|ConvertFrom-Json;foreach($id in 'C-STARTUP-003','C-STARTUP-005','C-STARTUP-006','C-STARTUP-007','C-STARTUP-008'){if($id -notin @($r.probes.featureId)){throw "missing $id"}};if(-not ($r.probes|Where-Object featureId -eq 'C-STARTUP-008').evidence.rollbackVerified){throw 'temp rollback failed'};'PASS: startup parsing, drift, guards and owned-temp rollback ran'}finally{Remove-Item $out -Force -ErrorAction SilentlyContinue}
